package org.example.board.comment;

import java.time.LocalDateTime;
import java.util.List;

import com.fasterxml.jackson.annotation.JsonInclude;
import org.example.board.post.AuthorResponse;

// 최상위 댓글은 replies(답글 목록)를 가진다. 답글에는 replies가 없다
public record CommentResponse(
        Long id,
        String content,
        AuthorResponse author,
        boolean deleted,
        LocalDateTime createdAt,
        @JsonInclude(JsonInclude.Include.NON_NULL) List<CommentResponse> replies) {

    static final String DELETED_CONTENT = "삭제된 댓글입니다";

    static CommentResponse reply(CommentRow c) {
        return new CommentResponse(c.id, c.content, new AuthorResponse(c.authorId, c.authorNickname), false,
                c.createdAt, null);
    }

    static CommentResponse top(CommentRow c, List<CommentResponse> replies) {
        if (c.deletedAt != null) {
            // 지운 부모는 내용·작성자를 숨기고 자리만 남긴다(답글이 고아가 되지 않게)
            return new CommentResponse(c.id, DELETED_CONTENT, null, true, c.createdAt, replies);
        }
        return new CommentResponse(c.id, c.content, new AuthorResponse(c.authorId, c.authorNickname), false,
                c.createdAt, replies);
    }
}

