package org.example.board.post;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.LinkedHashSet;
import java.util.Set;

import org.example.board.user.User;

public class Post {

    private Long id;

    private User author;

    private String title;

    private String content;

    private Visibility visibility;

    private int viewCount;

    private int likeCount;

    // MyBatis 경로에서는 Service가 post_tags INSERT를 명시적으로 수행한다.
    private Set<Tag> tags = new LinkedHashSet<>();

    private LocalDateTime createdAt;

    private LocalDateTime updatedAt;

    private LocalDateTime deletedAt;

    public Post() {
    }

    public Post(User author, String title, String content, Visibility visibility, Set<Tag> tags) {
        this.author = author;
        this.title = title;
        this.content = content;
        this.visibility = visibility;
        this.tags.addAll(tags);
        this.createdAt = now();
        this.updatedAt = this.createdAt;
    }

    private static LocalDateTime now() {
        return LocalDateTime.now().truncatedTo(ChronoUnit.SECONDS);
    }

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public User getAuthor() {
        return author;
    }

    public String getTitle() {
        return title;
    }

    public String getContent() {
        return content;
    }

    public Visibility getVisibility() {
        return visibility;
    }

    public int getViewCount() {
        return viewCount;
    }

    public int getLikeCount() {
        return likeCount;
    }

    public Set<Tag> getTags() {
        return tags;
    }

    public LocalDateTime getCreatedAt() {
        return createdAt;
    }

    public LocalDateTime getUpdatedAt() {
        return updatedAt;
    }

    public LocalDateTime getDeletedAt() {
        return deletedAt;
    }
}

